def main(query: str, text: str, prev_key_info: str) -> dict:
    """槽位对正：query=sys.query用户原话；text=需求规范化节点text；prev_key_info=conversation.key_info上轮存量。
    输出message=【槽位状态】各槽位已提供/未提供标记 + 【已确认信息】增量合并结果，由变量赋值节点覆写key_info。"""
    import re
    from datetime import date

    SLOTS = [
        ("生效日期",     ["生效日期", "生效时间"]),
        ("执行图号",     ["执行图号", "图号"]),
        ("调图项点描述", ["调图项点", "项点描述"]),
        ("风险项点",     ["风险"]),
        ("调图缘由类型", ["调图缘由", "缘由"]),
    ]
    REASON_WORDS = ["节假日运输", "沿线活动", "新线试运行", "客流变化", "节能测试", "限速", "小交路", "折返调整"]
    DATE_RE = re.compile(r"\d{4}年\d{1,2}月\d{1,2}日")
    GH_RE = re.compile(r"[A-Z]\d{5}")
    ALL_SLOT_NAMES = [s for s, _ in SLOTS] + ["ATS留存"]

    def _clean(v):
        return ((v or "").strip().strip("。；;")).strip()

    def _parse_prev(prev):
        """从上一轮持久化值里取【已确认信息】段的 槽位：值"""
        vals = {}
        if not prev:
            return vals
        in_body = False
        for line in prev.splitlines():
            t = line.strip()
            if t.startswith("【已确认信息】"):
                in_body = True
                continue
            if t.startswith("【") and in_body:
                break
            if not in_body or "：" not in t:
                continue
            name, _, v = t.partition("：")
            name, v = name.strip(), _clean(v)
            if name in ALL_SLOT_NAMES and v and v not in ("已提供", "未提供") and name not in vals:
                vals[name] = v
        return vals

    def _parse_normalized(text):
        """从【规范化需求】块解析 槽位：值；含【待补】的项不算已提供"""
        vals, provided = {}, set()
        if "【规范化需求】" not in text:
            return vals, provided
        body = text.split("【规范化需求】", 1)[1]
        for line in body.splitlines():
            t = line.strip()
            if t.startswith("【"):        # 进入下一个段落块即停
                break
            if "：" not in t:
                continue
            name, _, v = t.partition("：")
            name, v = name.strip(), _clean(v)
            if name in ALL_SLOT_NAMES and v:
                vals[name] = v
                if "待补" not in v:
                    provided.add(name)
        return vals, provided

    def _parse_missing_from_confirm(text):
        """确认单里点名的项=未提供"""
        if "确认单" not in text:
            return set()
        region = text.split("确认单", 1)[1].split("【规范化需求】", 1)[0]
        return {name for name, kws in SLOTS if any(kw in region for kw in kws)}

    def _extract_from_query(query):
        """本轮用户原话直接抽值（兜底，防模型透传原话）"""
        vals = {}
        m = DATE_RE.search(query)
        if m:
            vals["生效日期"] = m.group(0)
        elif re.search(r"即日起|今天起|当日起|明日启", query):
            vals["生效日期"] = date.today().strftime("%Y年%m月%d日") + "起"
        seen, uniq = set(), []
        for x in GH_RE.findall(query):
            if x not in seen:
                seen.add(x)
                uniq.append(x)
        if uniq:
            vals["执行图号"] = "、".join(uniq)
        reasons = [w for w in REASON_WORDS if w in query]
        if reasons:
            vals["调图缘由类型"] = "、".join(reasons)
        if re.search(r"无风险|风险[项点]*[：:]*\s*无", query):
            vals["风险项点"] = "无"
        elif re.search(r"有风险|风险[项点]*[：:]*\s*有", query):
            vals["风险项点"] = "有"
        return vals

    prev = prev_key_info or ""
    merged = _parse_prev(prev)
    norm_vals, norm_provided = _parse_normalized(text)
    merged.update(norm_vals)
    for k, v in _extract_from_query(query).items():
        if not merged.get(k):
            merged[k] = v
    if norm_provided:
        provided = set(norm_provided)
        missing = set(ALL_SLOT_NAMES) - provided
    else:
        confirm_missing = _parse_missing_from_confirm(text)
        provided = {s for s in ALL_SLOT_NAMES if merged.get(s)}
        missing = {s for s in confirm_missing if not merged.get(s)} or (set(ALL_SLOT_NAMES) - provided)
    status = "|".join(
        "{0}={1}".format(s, ("已提供（" + merged[s] + "）") if s in provided else "未提供")
        for s in ALL_SLOT_NAMES)
    # confirmed_text 只含已确认名值对（喂给下游C1，干净无状态标记）；
    # message 附带【槽位状态】行（供LLM下一轮累计判断，写入key_info持久化）
    confirmed_lines = []
    for s in ALL_SLOT_NAMES:
        if merged.get(s):
            confirmed_lines.append(s + "：" + merged[s])
    confirmed_text = "\n".join(confirmed_lines)
    lines = ["【槽位状态】" + status, "【已确认信息】"] + confirmed_lines
    if "【规范化需求】" in text and not missing:
        body_lines = []
        for line in text.split("【规范化需求】", 1)[1].splitlines():
            t = line.strip()
            if t.startswith("【"):
                break
            body_lines.append(line)
        body = "\n".join(body_lines).strip()
        if body:
            return {"message": body, "confirmed_text": confirmed_text}
    return {"message": "\n".join(lines), "confirmed_text": confirmed_text}

