def main(content: list[dict]) -> dict:
    import json
    def find_download(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == 'download' and isinstance(v, str) and v:
                    return v
                r = find_download(v)
                if r:
                    return r
        elif isinstance(obj, list):
            for v in obj:
                r = find_download(v)
                if r:
                    return r
        elif isinstance(obj, str):
            s = obj.strip()
            if s.startswith('{') or s.startswith('['):
                try:
                    return find_download(json.loads(s))
                except Exception:
                    return None
        return None
    url = find_download(content or [])
    return {'download_url': url or '',
            'extract_ok': bool(url)}

def main(query: str) -> dict:
    """截断用户输入作检索查询：重排模型输入上限短(约512 token)，
    超长原句直送rerank会500；取前200字符、压平空白，并丢弃非首行长粘贴。"""
    q = (query or "").strip()
    q = " ".join(q.split())          # 换行/连续空白压成单空格
    if len(q) > 200:
        q = q[:200]
    return {"search_query": q}
